package com.f1car.ui;

import com.f1car.FormulaGame;
import com.f1car.model.*;
import java.awt.Color;
import java.util.*;
import java.util.function.Consumer;

/** Explicit per-stage AND condition editing, bounded to the metrics already observed by the game. */
final class ActivityObjectivesHud {
    private static final Color INK=new Color(235,245,240),SOFT=new Color(162,186,189),MINT=new Color(76,235,193);
    private int index;private ActivityCard.Stage stage;private Double time,spread;private Integer contacts;private ActivitySection section;
    private boolean sectionView,pickEnd;private TrackLayout previewTrack;
    void open(int index,ActivityCard.Stage stage,ActivityObjective value) {this.index=index;this.stage=stage;time=value==null?null:value.timeLimit();contacts=value==null?null:value.contactLimit();spread=value==null?null:value.spreadLimit();section=value==null?null:value.section();sectionView=false;previewTrack=null;}
    void render(HudRenderer h,FormulaGame app,Consumer<ActivityObjective> adopt,Runnable cancel) {
        if(sectionView) {preview(h,app);return;}
        h.panel(70,230,1136,505,new Color(24,49,60));h.text("第 "+(index+1)+" 项复合条件 · 全部同时满足",90,274,25,MINT,true);h.wrapped(stage.goal(),90,311,1080,16,SOFT,24);
        h.smallButton(90,360,350,40,time==null?"总用时上限：关闭":"总用时上限：已开启",()->time=time==null?120d:null);h.smallButton(460,360,726,40,time==null?"点击左侧开启总完赛计时":"上限 "+time+" 秒 · 编辑",()->{if(time!=null) h.prompt("总用时上限 1–1200 秒，包含过起点前行驶",time.toString(),64,value->{try {double next=Double.parseDouble(value.strip());if(!Double.isFinite(next) || next<1 || next>1200) throw new NumberFormatException();time=next;}catch(NumberFormatException error) {app.notifyUser("请输入 1–1200 的有限秒数。");}});});
        boolean opponents=stage.kind().drivers>1;h.smallButton(90,422,350,40,!opponents?"对手接触：本项无对手":contacts==null?"对手接触上限：关闭":"对手接触上限：已开启",()->{if(opponents) contacts=contacts==null?0:null;});h.smallButton(460,422,726,40,contacts==null?"仅统计与对手接触，场景物件不计":"允许 "+contacts+" 段 · 编辑（追击保持零接触）",()->{if(contacts!=null) h.prompt("接触段上限 0–20；追击原目标仍要求零接触",contacts.toString(),32,value->{try {int next=Integer.parseInt(value.strip());if(next<0 || next>20 || stage.kind()==ActivityCard.Kind.CHASE && next!=0) throw new NumberFormatException();contacts=next;}catch(NumberFormatException error) {app.notifyUser("正赛允许 0–20 段；追击须为零。");}});});
        h.smallButton(90,484,350,40,stage.laps()<2?"圈速极差：至少两圈":spread==null?"圈速极差上限：关闭":"圈速极差上限：已开启",()->{if(stage.laps()>=2) spread=spread==null?2d:null;});h.smallButton(460,484,726,40,spread==null?"多圈活动可叠加极差上限":"极差 ≤ "+spread+" 秒 · 编辑",()->{if(spread!=null) h.prompt("全部有效圈极差 0.1–120 秒",spread.toString(),64,value->{try {double next=Double.parseDouble(value.strip());if(!Double.isFinite(next) || next<.1 || next>120) throw new NumberFormatException();spread=next;}catch(NumberFormatException error) {app.notifyUser("请输入 0.1–120 的有限秒数。");}});});
        h.smallButton(90,546,350,40,section==null?"路门分段目标：关闭":"路门分段目标：已开启",()->section=section==null?new ActivitySection(0,6,20):null);h.smallButton(460,546,726,40,section==null?"每圈都需通过指定分段；先开启再编辑":"路门 "+section.startGate()+" → "+section.endGate()+" ≤ "+section.limit()+" 秒 · 查看位置",()->{if(section!=null) try {var track=app.circuitById(stage.trackId());if(!track.geometryKey().equals(stage.geometry())) throw new IllegalArgumentException();previewTrack=track;pickEnd=false;sectionView=true;}catch(IllegalArgumentException error) {app.notifyUser("地图缺失、修订或未通过本机资格；先核对活动地图。");}});
        h.wrapped("附加条件与原目标同时满足。分段按十八个有序路门计时，每圈都需通过；恢复或路线无效仍须重试。接触段只统计对手。",90,615,1080,15,SOFT,22);
        h.smallButton(90,663,350,42,"清除本项附加条件",()->adopt.accept(null));h.smallButton(460,663,350,42,"取消，保留活动草稿",cancel);h.smallButton(830,663,356,42,"预览并采用到草稿",()->{if(time==null && contacts==null && spread==null && section==null) {adopt.accept(null);return;}try {var value=new ActivityObjective(index,time,contacts,spread,section);if(!value.applicable(stage)) throw new IllegalArgumentException();var lines=new ArrayList<String>();lines.add("原目标："+stage.goal());lines.addAll(value.describe());lines.add("全部附加条件与原目标同时满足；只修改未保存活动草稿，保存时创建新卡和新的成绩条件。");if(section!=null) lines.add("分段采用实际有序通过路门时的更新步末时间，非高精度插值；不能仅凭地图资格认定时限可达。");h.review("采用本项复合条件？",lines,"采用到活动草稿",()->adopt.accept(value));}catch(IllegalArgumentException error) {app.notifyUser("条件不适用于本项圈数或对手设置，请先调整。");}});
    }
    private void preview(HudRenderer h,FormulaGame app) {h.panel(70,230,1136,505,new Color(24,49,60));h.text("分段位置 · "+stage.trackName(),90,275,24,MINT,true);h.smallButton(90,294,350,34,pickEnd?"当前点选：终点":"当前点选：起点",()->pickEnd=!pickEnd);h.text("点选有序路门；0/18 是同一条起终线",460,317,16,SOFT);h.activitySectionPreview(previewTrack,section,gate->{if(pickEnd) {int end=gate==0?18:gate;if(end<=section.startGate()) {app.notifyUser("终点须在起点之后；需要跨起终线时请拆成两段活动。");return;}section=new ActivitySection(section.startGate(),end,section.limit());}else section=new ActivitySection(gate,Math.max(gate+1,section.endGate()),section.limit());});h.smallButton(90,610,350,40,"填写起终点与时限",()->editSection(h,app));h.smallButton(460,610,726,40,"返回复合条件编辑",()->sectionView=false);h.wrapped(section.describe(),90,680,1080,16,SOFT,23);}
    private void editSection(HudRenderer h,FormulaGame app) {var original=section;h.prompt("起始路门 0–17，0 为起点",Integer.toString(original.startGate()),32,text->{try {int start=Integer.parseInt(text.strip());if(start<0 || start>=18) throw new NumberFormatException();h.prompt("结束路门须大于起始，最大 18 为该圈终点",Integer.toString(Math.max(start+1,original.endGate())),32,endText->{try {int end=Integer.parseInt(endText.strip());if(end<=start || end>18) throw new NumberFormatException();h.prompt("每个有效圈的分段上限 0.1–1200 秒",Double.toString(original.limit()),64,limitText->{try {var value=new ActivitySection(start,end,Double.parseDouble(limitText.strip()));h.review("设置这段驾驶目标？",List.of(value.describe(),"按赛道长度十八等分的有序路门选择，不跨圈拼段。分段达标后仍需完成原活动目标；只改变未保存草稿。"),"设置这段目标",()->section=value);}catch(IllegalArgumentException error) {app.notifyUser("请输入 0.1–1200 的有限秒数。");}});}catch(NumberFormatException error) {app.notifyUser("结束路门须大于起始，且不超过 18。");}});}catch(NumberFormatException error) {app.notifyUser("起始路门须为 0–17 的整数。");}});}
}
